#include "stdlib/blas/ext/base/ndarray/dsort.h"
#include "stdlib/blas/ext/base/dsort.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Sorts a one-dimensional double-precision floating-point ndarray.
*
* @param arrays    list containing an input ndarray and a zero-dimensional order ndarray
*/
void stdlib_blas_ext_ndarray_dsort( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *ord = arrays[ 1 ];
	double order = *(double *)stdlib_ndarray_data( ord );
	API_SUFFIX(stdlib_strided_dsort_ndarray)( stdlib_ndarray_dimension( x, 0 ), order, (double *)stdlib_ndarray_data( x ), stdlib_ndarray_stride_elements( x, 0 ), stdlib_ndarray_offset_elements( x ) );
}
